def replace_char(s, i, c):
    return s[:i] + c + s[i + 1:]

def id(c):
    return ord(c) - ord('A')

def evaluate(s):
    t = s[::-1]
    ans = 0
    max_id = -1
    for x in t:
        i = id(x)
        if max_id > i:
            ans -= 10 ** i
        else:
            ans += 10 ** i
        max_id = max(max_id, i)
    return ans

